def round_half_to_even(n: float) -> float:
    """
    Round a floating-point number according to the round half to even method.
    """
    if n == 0:
        return 0
    integer_part = int(n)
    fractional_part = n - integer_part
    if fractional_part == 0.5:
        if integer_part % 2 == 0:
            return integer_part
        else:
            return integer_part + 1
    else:
        return round(n)

