def parser_flags(parser: argparse.ArgumentParser) -> typing.Optional[str]:
    """
    The function takes an argparse.ArgumentParser instance and returns a space-separated string of its argument flags.
    If the parser has no arguments, it returns None.
    """
    # Check if the parser has any arguments
    if not parser._actions:
        return None

    # Extract the list of argument groups and their respective arguments
    groups = parser._action_groups
    flags = []

    for group in groups:
        group_flags = []
        for action in group._group_actions:
            if action.dest != argparse.SUPPRESS:
                group_flags.append(f"--{action.dest}")
        if group_flags:
            flags.append(f"({','.join(group_flags)})")

    # Format the argument flags into a space-separated string
    return ' '.join(flags)

