import tarfile

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[pathlib.PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    @param archive_path : archive file path
    @param filename: File name
    @param tmp_path: Temporary file path
    @return Repo URL
    """
    # Ensure tmp_path is a pathlib.Path object
    if isinstance(tmp_path, str):
        tmp_path = pathlib.Path(tmp_path)

    # Create a temporary directory to extract the archive
    temp_dir = tmp_path / "extracted_archive"
    temp_dir.mkdir(exist_ok=True)

    # Determine the type of archive and extract it
    if archive_path.endswith(".zip"):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            zip_ref.extractall(temp_dir)
    elif archive_path.endswith(".tar") or archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
        with tarfile.open(archive_path, 'r') as tar_ref:
            tar_ref.extractall(temp_dir)
    else:
        raise ValueError("Unsupported archive format. Only ZIP and TAR/TAR.GZ/TGZ are supported.")

    # Find the repository URL
    repo_url = None
    for root, dirs, files in os.walk(temp_dir):
        for file in files:
            if file.endswith(".repo"):
                repo_file_path = pathlib.Path(root) / file
                with open(repo_file_path, 'r') as repo_file:
                    repo_url = repo_file.readline().strip()
                    break
        if repo_url:
            break

    if repo_url is None:
        raise FileNotFoundError("Repository URL not found in the extracted files.")

    return repo_url

