import datetime
from typing import Optional

def parse_frequency(frequency: Optional[str]) -> Optional[datetime.timedelta]:
    if frequency is None or frequency == 'always':
        return None

    # Regular expression to match the frequency pattern
    pattern = re.compile(r'^(\d+)\s*(seconds|minutes|hours|days|weeks|months|years)$')
    match = pattern.match(frequency)

    if not match:
        raise ValueError("Invalid frequency string. Expected format: 'number timeunit'")

    number = int(match.group(1))
    timeunit = match.group(2)

    if timeunit == 'seconds':
        return datetime.timedelta(seconds=number)
    elif timeunit == 'minutes':
        return datetime.timedelta(minutes=number)
    elif timeunit == 'hours':
        return datetime.timedelta(hours=number)
    elif timeunit == 'days':
        return datetime.timedelta(days=number)
    elif timeunit == 'weeks':
        return datetime.timedelta(weeks=number)
    elif timeunit == 'months':
        # Handling months is more complex and not covered by timedelta
        # For simplicity, we will not support months in this implementation
        raise ValueError("Months are not supported in this implementation")
    elif timeunit == 'years':
        # Similarly, years are not supported by timedelta
        raise ValueError("Years are not supported in this implementation")
    else:
        raise ValueError("Unsupported time unit")

