from flask import Flask, request, jsonify
import json

# Follow design
class Bookmark:
    def __init__(self, title: str, url: str):
        self.title = title
        self.url = url

    @staticmethod
    def from_raw_value(value: str) -> 'Bookmark':
        parts = value.split()
        if len(parts) < 2:
            raise ValueError("Each bookmark must have at least a title and a URL")
        title = parts[0]
        url = parts[1]
        return Bookmark(title, url)

class Bookmarks:
    def __init__(self, bookmarks: List[Bookmark]):
        self.bookmarks = bookmarks

    def add_bookmark(self, bookmark: Bookmark):
        self.bookmarks.append(bookmark)

    def search_bookmarks(self, query: str) -> List[Bookmark]:
        if not query:
            return self.bookmarks
        return [bookmark for bookmark in self.bookmarks if query in bookmark.title or query in bookmark.url]

# Flask app setup
app = Flask(__name__)

# In-memory storage for bookmarks
bookmarks_store = Bookmarks([])

# Import bookmarks from a file
@app.route('/import', methods=['POST'])
def import_bookmarks():
    data = request.json
    if 'file' not in data:
        return jsonify({"error": "No file provided"}), 400

    file_content = data['file']
    try:
        if file_content.strip().startswith('{'):
            raw_values = json.loads(file_content)
        else:
            raw_values = file_content.strip().split('\n')
        bookmarks = [Bookmark.from_raw_value(value) for value in raw_values]
        bookmarks_store.bookmarks = bookmarks
        return jsonify({"message": "Bookmarks imported successfully"}), 200
    except (ValueError, json.JSONDecodeError) as e:
        return jsonify({"error": str(e)}), 400

# Add a new bookmark
@app.route('/bookmarks', methods=['POST'])
def add_bookmark():
    data = request.json
    if 'title' not in data or 'url' not in data:
        return jsonify({"error": "Title and URL are required"}), 400

    title = data['title']
    url = data['url']
    new_bookmark = Bookmark(title, url)
    bookmarks_store.add_bookmark(new_bookmark)
    return jsonify({"message": "Bookmark added successfully"}), 201

# Search for bookmarks
@app.route('/search', methods=['GET'])
def search_bookmarks():
    query = request.args.get('query', '')
    results = bookmarks_store.search_bookmarks(query)
    bookmark_list = [{"title": result.title, "url": result.url} for result in results]
    return jsonify(bookmark_list), 200

if __name__ == '__main__':
    app.run(debug=True)
